namespace {

using Json = nlohmann::json;

void write_json(httplib::Response& response, int status, const Json& payload) {
    response.status = status;
    response.set_content(payload.dump(), "application/json; charset=utf-8");
}

Json error_payload(const std::string& code, const std::string& message) {
    return {{"ok", false}, {"error", {{"code", code}, {"message", message}}}};
}

}  // namespace

int main(int argc, char** argv) {
    std::string host = "127.0.0.1";
    int port = 8080;
    std::string detector_path;
    for (int index = 1; index < argc; ++index) {
        const std::string argument = argv[index];
        if (argument == "--host" && index + 1 < argc) {
            host = argv[++index];
        } else if (argument == "--port" && index + 1 < argc) {
            port = std::stoi(argv[++index]);
        } else if (argument == "--detector" && index + 1 < argc) {
            detector_path = argv[++index];
        } else {
            std::cerr << "Usage: medvision_http [--host HOST] [--port PORT] [--detector MODEL.onnx]\n";
            return EXIT_FAILURE;
        }
    }

    auto detector = std::make_shared<medvision::OnnxRuntimeBackend>();
    if (!detector_path.empty()) {
        try {
            detector->load(detector_path);
        } catch (const std::exception& error) {
            std::cerr << "MODEL_LOAD=FAIL error=" << error.what() << "\n";
            return EXIT_FAILURE;
        }
    }

    httplib::Server server;
    server.Get("/health", [detector](const httplib::Request&, httplib::Response& response) {
        write_json(response, 200, {
            {"ok", true},
            {"service", "medvision_http"},
            {"runtime", "cpp"},
            {"python_required", false},
            {"backend", detector->name()},
            {"detector_loaded", detector->loaded()},
        });
    });
    server.Post("/v1/infer/image", [detector](const httplib::Request&, httplib::Response& response) {
        if (!detector->loaded()) {
            write_json(response, 503, error_payload("model_not_loaded", "A production detector ONNX package is not loaded"));
            return;
        }
        write_json(response, 501, error_payload("image_adapter_not_built", "Build the OpenCV feature after a detector model passes the data gate"));
    });
    server.Post("/v1/streams", [](const httplib::Request&, httplib::Response& response) {
        write_json(response, 501, error_payload("video_adapter_not_built", "Real-time video starts after the detector ONNX parity gate"));
    });
    server.Get(R"(/v1/streams/([^/]+)/latest)", [](const httplib::Request&, httplib::Response& response) {
        write_json(response, 404, error_payload("stream_not_found", "No active stream has this id"));
    });
    server.Delete(R"(/v1/streams/([^/]+))", [](const httplib::Request&, httplib::Response& response) {
        write_json(response, 404, error_payload("stream_not_found", "No active stream has this id"));
    });

    std::cout << "MEDVISION_HTTP_URL=http://" << host << ':' << port << "\n";
    if (!server.listen(host, port)) {
        std::cerr << "HTTP_LISTEN=FAIL host=" << host << " port=" << port << "\n";
        return EXIT_FAILURE;
    }
    return EXIT_SUCCESS;
}

