<h1>Live Device and Contact Point</h1><p class="lead">Camera frames stay on the local 127.0.0.1 service. Red is stable. Orange and pink are raw frame predictions.</p>
<div class="bar"><button id="start">Start camera</button><button id="stop" class="secondary" disabled>Stop</button><div id="status">Checking local service.</div></div>
<div class="stage"><video id="video" autoplay muted playsinline></video><canvas id="view"></canvas></div>
<div class="legend"><span><i class="dot" style="background:#ff3030"></i>Stable device/contact</span><span><i class="dot" style="background:#ff971c"></i>Raw device</span><span><i class="dot" style="background:#ff2d9a"></i>Raw contact</span><span><i class="dot" style="background:#ffe86b"></i>Review or stale</span></div>
<div class="grid"><div class="metric"><small>Provider</small><span id="provider">-</span></div><div class="metric"><small>Response FPS</small><span id="fps">-</span></div><div class="metric"><small>Latency</small><span id="latency">-</span></div><div class="metric"><small>Dropped frames</small><span id="dropped">0</span></div></div>
<p class="hint">Click Start camera and allow browser permission. Yellow review text means the frame is uncertain; the service does not invent a contact point.</p>
</main><script>
const video=document.querySelector("#video"),view=document.querySelector("#view"),ctx=view.getContext("2d"),capture=document.createElement("canvas");
const status=document.querySelector("#status"),startButton=document.querySelector("#start"),stopButton=document.querySelector("#stop");
let socket=null,stream=null,timer=null,raf=null,frameId=0,latest=null,responses=0,windowStart=performance.now();
function setStatus(text){status.textContent=text}
function drawBox(box,color,label){if(!box)return;const x1=box[0],y1=box[1],x2=box[2],y2=box[3];ctx.strokeStyle=color;ctx.lineWidth=color==="#ff3030"?6:4;ctx.strokeRect(x1,y1,x2-x1,y2-y1);ctx.fillStyle=color;ctx.font="bold 16px ui-monospace, monospace";ctx.fillText(label,x1+5,y1+20)}
function drawPoint(point,color,label){if(!point)return;const x=point[0],y=point[1],r=Math.max(12,Math.min(view.width,view.height)*.018);ctx.strokeStyle=color;ctx.lineWidth=5;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.stroke();ctx.beginPath();ctx.moveTo(x-r-6,y);ctx.lineTo(x+r+6,y);ctx.moveTo(x,y-r-6);ctx.lineTo(x,y+r+6);ctx.stroke();ctx.fillStyle=color;ctx.font="bold 16px ui-monospace, monospace";ctx.fillText(label,x+r+8,y+r+8)}
function paint(){if(video.videoWidth){if(view.width!==video.videoWidth){view.width=video.videoWidth;view.height=video.videoHeight;capture.width=view.width;capture.height=view.height}ctx.drawImage(video,0,0,view.width,view.height);if(latest){drawBox(latest.raw.device.bbox,"#ff971c","RAW DEVICE");drawBox(latest.stable.device_bbox,"#ff3030","DEVICE");drawPoint(latest.raw.contact.point,"#ff2d9a","RAW CONTACT");drawPoint(latest.stable.contact_point,"#ff3030","CONTACT");if(latest.needs_review){ctx.fillStyle="#ffe86b";ctx.font="bold 22px ui-monospace, monospace";ctx.fillText(latest.stale?"STALE / NEEDS REVIEW":"NEEDS REVIEW",14,32)}}}raf=requestAnimationFrame(paint)}
function captureFrame(){if(!socket||socket.readyState!==WebSocket.OPEN||!video.videoWidth)return;capture.getContext("2d").drawImage(video,0,0,capture.width,capture.height);const id=frameId++;socket.send(JSON.stringify({type:"frame_meta",frame_id:id,source_timestamp_ms:Math.round(performance.now())}));capture.toBlob(function(blob){if(blob&&socket.readyState===WebSocket.OPEN)socket.send(blob)},"image/jpeg",.78)}
async function start(){try{stream=await navigator.mediaDevices.getUserMedia({video:{width:{ideal:1280},height:{ideal:720}},audio:false});video.srcObject=stream;await video.play();const scheme=location.protocol==="https:"?"wss://":"ws://";socket=new WebSocket(scheme+location.host+"/v1/stream/infer");socket.onmessage=function(event){const message=JSON.parse(event.data);if(message.event==="connected"){document.querySelector("#provider").textContent=message.execution_provider;setStatus("Camera connected. Receiving results.");return}if(!message.ok){setStatus("Inference error: "+message.error);return}latest=message.result;responses++;document.querySelector("#latency").textContent=latest.timings_ms.end_to_end.toFixed(1)+" ms";document.querySelector("#dropped").textContent=latest.dropped_frames;const now=performance.now();if(now-windowStart>=1000){document.querySelector("#fps").textContent=responses;responses=0;windowStart=now}};socket.onerror=function(){setStatus("Local service connection failed.")};timer=setInterval(captureFrame,100);raf=requestAnimationFrame(paint);startButton.disabled=true;stopButton.disabled=false;setStatus("Requesting camera permission.")}catch(error){setStatus("Cannot open camera: "+error.message)}}
function stop(){clearInterval(timer);cancelAnimationFrame(raf);if(socket)socket.close();if(stream)stream.getTracks().forEach(function(track){track.stop()});latest=null;startButton.disabled=false;stopButton.disabled=true;setStatus("Stopped.")}
startButton.addEventListener("click",start);stopButton.addEventListener("click",stop);
fetch("/health").then(function(response){return response.json()}).then(function(data){document.querySelector("#provider").textContent=data.execution_provider;setStatus("Local inference service ready.")}).catch(function(){setStatus("Local inference service is not running.")});
